/*
 * 治療エビデンスのデータ
 *
 * 構成
 *   DISEASES  疾患 → 場面（初発 / 再発・難治）→ ガイドライン（JSH / NCCN）→ 状況 → 選択肢
 *   REGIMENS  治療法（選択肢から reg で参照）。trials に根拠となる試験を並べる
 *   TRIALS    臨床試験の要約（dz：表示する疾患）
 *
 * 選択肢 { reg: 治療法のキー, label: 表示名, note: 補足, focus: [この場面の根拠として先頭に出す試験] }
 *   reg がない選択肢はタップできない文字だけの行になる
 * 試験の結果 { ep: 評価項目, a: 試験群, b: 対照群, hr: 群間比較, p: true なら主要評価項目 }
 *   単群試験は arms を1つにし、b を省く
 *
 * 数値は原著（主解析）を基本とし、長期追跡は updates に記載。
 */

